G=load(); print(sorted(G))
def solve(g,v):
    h=len(g); w=len(g[0])
    # mark each zero cell that lies between two v's in its row AND sees one above/below in same col
    out=[row[:] for row in g]
    for i in range(h):
        for j in range(w):
            if g[i][j]!=0: continue
            between=any(k<j for k in range(w) if g[i][k]==v) and any(k>j for k in range(w) if g[i][k]==v)
            below=any(g[i+k][j]==v for k in range(h-i))
            above=any(g[i-k][j]==v for k in range(i+1))
            if between and below and above: out[i][j]=2
    return out
